    @Override
    public AvailabilityResponse getHotelPrice(PriceReq priceReq, String sHotelId) {
        String date = Encryption.getDate();
        String apiClientToken = Encryption.generateSignature("POST", availability, date, secret);
        AvailabilityRequest availabilityRequest = AvailabilityRequest.builder()
                .check_in(priceReq.getCheckIn())
                .check_out(priceReq.getCheckout())
                .hotel_id(Integer.parseInt(sHotelId))
                .room_number(priceReq.getRoomNum())
                .adult_number(priceReq.getAdultNum())
                .kids_number(priceReq.getChildNum()).build();
        ResponseResult<AvailabilityResponse> roomInfoResponse = new AvailabilityAccess(host + availability, apiClientKey, date, apiClientToken, rateLimiter).access(availabilityRequest);
        if (roomInfoResponse == null) {
            return null;
        }
        return roomInfoResponse.getData();
    }

    @Override
    public PreBookResponse checkPrice(CheckPriceReq priceReq) {
        String date = Encryption.getDate();
        String apiClientToken = Encryption.generateSignature("POST", prebook, date, secret);
        PreBookRequest preBookRequest = PreBookRequest.builder()
                .check_in(priceReq.getCheckIn())
                .check_out(priceReq.getCheckOut())
                .hotel_id(Integer.parseInt(priceReq.getSHotelId()))
                .room_key(priceReq.getSProductId())
                .room_number(priceReq.getRoomNum())
                .adult_number(priceReq.getAdultCount())
                .kids_number(0).build();
        ResponseResult<PreBookResponse> preBookResponse = new PreBookAccess(host + prebook, apiClientKey, date, apiClientToken).access(preBookRequest);
        return preBookResponse.getData();
    }
